#include <iostream>
#include <string>
#include <typeinfo>
using namespace std;

class Cat {
public:
    virtual ~Cat() {}
};

class OrangeCat : public Cat {};
class TabbyCat : public Cat {};

int main() {
    OrangeCat o;
    TabbyCat t;
    Cat* p = &o;
    cout << typeid(*p).name() << endl;
    cout << (dynamic_cast<TabbyCat*>(p) == nullptr ? "没照出来" : "照出来了") << endl;
    p = &t;
    cout << (dynamic_cast<TabbyCat*>(p) == nullptr ? "没照出来" : "照出来了") << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    int weight;
    OrangeCat() : weight(7) {}
};

class TabbyCat : public Cat {
public:
    int stripes;
    TabbyCat() : stripes(13) {}
};

int main() {
    TabbyCat t;
    Cat* p = &t;
    OrangeCat* hard = static_cast<OrangeCat*>(p);
    OrangeCat* soft = dynamic_cast<OrangeCat*>(p);
    cout << (hard == nullptr ? "牌子是空的" : "牌子有货") << endl;
    cout << (soft == nullptr ? "牌子是空的" : "牌子有货") << endl;
    return 0;
}
